mapper.select:
SELECT s.id AS id, s.content AS content, s.create_time AS create_time, s.content_type AS content_type, IFNULL(browse_count.browse_count, 0) AS browse_count, IFNULL(like_count.like_count, 0) AS like_count FROM share s LEFT JOIN ( SELECT post_id, COUNT(*) AS browse_count FROM browse WHERE type = 1 GROUP BY post_id ) browse_count ON s.id = browse_count.post_id LEFT JOIN ( SELECT target_id AS post_id, COUNT(*) AS like_count FROM likes WHERE type = 1 AND status = 0 GROUP BY target_id ) like_count ON s.id = like_count.post_id WHERE s.author_id = #{userId} AND s.status = 2
AND ( s.create_time < #{lastCreateTime} OR (s.create_time = #{lastCreateTime} AND s.id < #{lastId}) )
ORDER BY s.create_time DESC, s.id DESC LIMIT #{size}
